		if idx[i] > idx[i-1] {
			idx[i], idx[i-1] = idx[i-1], idx[i]
			sort.Ints(idx[i:])
			return true
		}
	}

	return false
}

func main() {
	var n, a, b int
	fmt.Scanf("%d\n%d\n%d", &n, &a, &b)
	frames := make([]int, 6)
	idxs := make([]int, 6)
	for i := 0; i < 6; i++ {
		if i < 4 {
			frames[i] = a
		} else {
			frames[i] = b
		}
		idxs[i] = i
	}

	bestAnswer := 6
	for {
		count, leftover := 0, 0
		for i := 0; i < 6; i++ {
			if leftover < frames[idxs[i]] {
				count++
				leftover = n
			}
			leftover -= frames[idxs[i]]
		}
		if count < bestAnswer {
			bestAnswer = count
		}
		if !next_permutation(idxs) {
			break
		}
	}

	fmt.Println(bestAnswer)
}
